import base64, collections, csv, gc, hashlib, io, json, random, subprocess, sys, tarfile, time, traceback
from pathlib import Path
subprocess.run([sys.executable, '-m', 'pip', 'uninstall', '-y', 'torchao'], check=True)
subprocess.run([sys.executable, '-m', 'pip', 'install', '--no-deps', 'bitsandbytes>=0.46.1,<1'], check=True)
import importlib.metadata
import torch
if not torch.cuda.is_available(): raise RuntimeError('CUDA GPU is required')
print('GPU', torch.cuda.get_device_name(0), flush=True)
raw = base64.b64decode('')
if hashlib.sha256(raw).hexdigest() != '49f0abdfcef2eb5157ce6eb54c858aa519e586a6090569410421cf74c08462dc': raise RuntimeError('source archive hash mismatch')
root = Path('/kaggle/temp/distillation-src'); root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()), mode='r:') as inner:
            inner.extractall(root, filter='data')
sys.path[:0] = [str(root / 'packages/ekido_core'), str(root / 'runtime')]
from ekido_core.recipes import recipe
from ekido_runtime.distill import run_distillation
recipes = ['faq-bot-hinglish']
for name in recipes:
    subprocess.run([sys.executable, '-I', str(root / 'experiments/recipes/validate_dataset.py'),
                    str(root / 'experiments/recipes' / name)], check=True)
out = Path('/kaggle/working/distillation-matrix'); out.mkdir(parents=True, exist_ok=True)
config = {'micro_batch': 1, 'accumulation': 8, 'amp': 'fp16', 'grad_checkpointing': True,
          'attention_impl': 'sdpa', 'loader_workers': 0}
summary = {'core_revision': '0a9db037170024a1f32748e0b5dcbe14a1a88a3a', 'worker_revision': '69f37fe0dd5b88f8773085f7f1dbdd221d2b8906',
           'seed_selection': 'Random(42), 10 per class for sentiment and 30 random for other recipes',
           'teacher_model': 'Qwen/Qwen2.5-7B-Instruct', 'teacher_4bit': True,
           'bitsandbytes_version': importlib.metadata.version('bitsandbytes'),
           'student_model': 'Qwen/Qwen2.5-1.5B-Instruct', 'runs': {}}
for name in recipes:
    print('START', name, flush=True)
    folder = root / 'experiments/recipes' / name
    with (folder / 'train.csv').open(encoding='utf-8', newline='') as f: train = list(csv.DictReader(f))
    with (folder / 'test.csv').open(encoding='utf-8', newline='') as f: test = list(csv.DictReader(f))
    rng = random.Random(42)
    if name == 'review-sentiment':
        seeds = [row for label in ('positive', 'negative', 'neutral')
                 for row in rng.sample([row for row in train if row['label'] == label], 10)]
    else:
        seeds = rng.sample(train, 30)
    source = recipe(name).columns[0]
    norm = lambda x: ' '.join(x.casefold().split())
    if {norm(row[source]) for row in seeds} & {norm(row[source]) for row in test}:
        raise RuntimeError('seed/test overlap for ' + name)
    target = out / name; target.mkdir(parents=True, exist_ok=True)
    (target / 'seeds.json').write_text(json.dumps(seeds, ensure_ascii=False, indent=2), encoding='utf-8')
    torch.cuda.reset_peak_memory_stats()
    started = time.monotonic()
    try:
        result = run_distillation(name, seeds, test, target, student_id='Qwen/Qwen2.5-1.5B-Instruct',
                 student_revision='989aa7980e4cf806f80c7fef2b1adb7bc71aa306', per_seed=3,
                 steps=50, device='cuda', exec_config=config, teacher_4bit=True)
        summary['runs'][name] = {'status': 'complete', 'seed_rows': len(seeds),
                                 'generated_rows': result['generated_rows'],
                                 'base': result['student_base_eval']['pass_rate'],
                                 'student': result['student_eval']['pass_rate'],
                                 'whole_run_seconds': round(time.monotonic() - started, 2),
                                 'peak_allocated_bytes_teacher_and_student': torch.cuda.max_memory_allocated()}
    except Exception as exc:
        summary['runs'][name] = {'status': 'error', 'error': str(exc)}
        traceback.print_exc()
    finally:
        (out / 'summary.json').write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding='utf-8')
        gc.collect(); torch.cuda.empty_cache()
    print('FINISH', name, summary['runs'][name], flush=True)
if any(row['status'] != 'complete' for row in summary['runs'].values()): raise RuntimeError('One or more recipes failed')
